// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *ItemUnitOfMeasure) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, ItemUnitOfMeasureTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "qty_per_unit_of_measure":
			column = "qty_per_unit_of_measure"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Item_Unit_of_Measure", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Item_Unit_of_Measure.%s: %w", column, err)
		}
		switch column {
		case "qty_per_unit_of_measure":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Item_Unit_of_Measure.%s: %w", column, err)
			}
			t.Qty_per_unit_of_measure = d
		}
	}
	return nil
}

